function r(){const t=Date.now(),n=720*60*1e3;return Math.floor(t/n)}function c(t){return function(){t|=0,t=t+1831565813|0;let n=Math.imul(t^t>>>15,1|t);return n=n+Math.imul(n^n>>>7,61|n)^n,((n^n>>>14)>>>0)/4294967296}}function i(t,n=0){if(!t||t.length<=1)return t;const f=r()+n,l=c(f),o=[...t];for(let e=o.length-1;e>0;e--){const u=Math.floor(l()*(e+1));[o[e],o[u]]=[o[u],o[e]]}return o}export{i as t};
